function pageAdminEarlyAccess(){
  const cards=[['Total requests','total'],['New requests','new'],['Contacted customers','contacted'],['Pending follow-ups','followups'],['Demo planned','demo'],['Converted clients','converted']];
  return {title:'DEFENSOWRIX Early Access | Admin',desc:'Manage authorized Early Access enquiries.',noindex:true,html:`
  <section><header><p class="group">SOWRIX / DEFENSOWRIX</p><h1>Early Access requests</h1><p class="lead">Customer interest only. DEFENSOWRIX remains under development.</p></header>
  <section aria-label="Early Access request counts" class="sx-ea-kpis" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,170px),1fr));gap:14px;margin:24px 0">${cards.map(([label,key])=>`<article class="admin-card"><p>${label}</p><strong id="ea-kpi-${key}" aria-live="polite">—</strong></article>`).join('')}</section>
  <section class="admin-card" aria-label="Early Access request management"><div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center"><label>Search requests<input id="ea-search" type="search" autocomplete="off" placeholder="Request ID, customer or company"></label><label>Status<select id="ea-status"><option value="">All statuses</option><option>new</option><option>contacted</option><option>waiting</option><option>converted</option><option>closed</option></select></label><button class="btn btn-ghost" id="ea-export" type="button">Export CSV</button></div>
  <p id="ea-page-status" role="status" aria-live="polite">Data has not loaded.</p>
  <div style="overflow:auto"><table><thead><tr><th>Request ID</th><th>Customer / company</th><th>Solutions</th><th>Devices</th><th>Submitted</th><th>Assignment</th><th>Status</th><th>Details</th></tr></thead><tbody id="ea-request-rows"></tbody></table></div>
  <div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end;margin-top:16px"><button class="btn btn-ghost" id="ea-prev" type="button" disabled>Previous</button><span id="ea-page-number" aria-live="polite">—</span><button class="btn btn-ghost" id="ea-next" type="button" disabled>Next</button><button class="btn btn-ghost" id="ea-refresh" type="button">Refresh</button></div><div id="ea-detail" class="admin-card" hidden></div></section></section>`};
}

function initAdminEarlyAccess(){
 const root=document.getElementById('ea-request-rows');if(!root||root.dataset.bound)return;root.dataset.bound='1';
 const status=document.getElementById('ea-page-status'),pageLabel=document.getElementById('ea-page-number');let page=1,totalPages=1,delay;
 const call=async(action,data={})=>{const r=await window.SOWRIXSession.request('/api/admin/early-access',{action,data});return r.data;};
 const load=async()=>{status.textContent='Loading Early Access requests…';root.replaceChildren();try{
  const [counts,rows]=await Promise.all([call('counts'),call('list',{page,page_size:25,search:document.getElementById('ea-search').value.trim(),status:document.getElementById('ea-status').value||undefined})]);
  for(const key of ['total','new','contacted','converted'])document.getElementById('ea-kpi-'+key).textContent=Number.isFinite(Number(counts[key]))?Number(counts[key]).toLocaleString():'—';
  for(const key of ['followups','demo'])document.getElementById('ea-kpi-'+key).textContent='—';
  const items=Array.isArray(rows)?rows:[];totalPages=Math.max(1,Math.ceil((Number(counts.total)||0)/25));pageLabel.textContent='Page '+page+' of '+totalPages;
  document.getElementById('ea-prev').disabled=page<=1;document.getElementById('ea-next').disabled=page>=totalPages;
  if(!items.length){status.textContent='No requests match these filters.';const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=8;td.textContent='No requests found.';tr.append(td);root.append(tr);return;}
  status.textContent='Showing '+items.length+' request(s).';for(const item of items){const tr=document.createElement('tr');for(const value of [item.request_id,[item.full_name,item.company_name].filter(Boolean).join(' · '),(item.interested_solutions||[]).join(', '),item.approximate_device_count,item.created_at?new Date(item.created_at).toLocaleString():'—',item.assigned_employee?'Assigned':'Unassigned',item.status]){const td=document.createElement('td');td.textContent=String(value??'—');tr.append(td);}const td=document.createElement('td'),button=document.createElement('button');button.type='button';button.className='btn btn-ghost';button.textContent='View';button.addEventListener('click',()=>detail(item.id));td.append(button);tr.append(td);root.append(tr);}
 }catch(error){status.textContent=/permission|admin|denied|unauthorized/i.test(error.message)?'Access denied. Your account cannot view these requests.':'Could not load Early Access data. Please refresh and try again.';root.replaceChildren();for(const key of ['total','new','contacted','followups','demo','converted'])document.getElementById('ea-kpi-'+key).textContent='—';}};
 const detail=async id=>{const panel=document.getElementById('ea-detail');panel.hidden=false;panel.textContent='Loading request details…';try{const d=await call('detail',{id}),h=await call('history',{id});panel.replaceChildren();const heading=document.createElement('h2');heading.textContent='Request details · '+String(d.request?.request_id||'');panel.append(heading);for(const [k,v] of Object.entries(d.request||{})){if(!['request_id','full_name','company_name','business_email','contact_number','interested_solutions','approximate_device_count','business_requirements','status','follow_up_at','created_at','updated_at'].includes(k))continue;const p=document.createElement('p');p.textContent=k.replaceAll('_',' ')+': '+(Array.isArray(v)?v.join(', '):String(v??'—'));panel.append(p);}const hist=document.createElement('h3');hist.textContent='History';panel.append(hist);for(const row of (Array.isArray(h)?h:[])){const p=document.createElement('p');p.textContent=[row.event_type,row.previous_status,row.new_status,row.note,row.created_at].filter(Boolean).join(' · ');panel.append(p);}}catch(_){panel.textContent='Request details are unavailable or access was denied.';}};
 const exportCsv=async()=>{const button=document.getElementById('ea-export');button.disabled=true;try{const response=await window.SOWRIXSession.request('/api/admin/early-access',{action:'export',data:{}},{raw:true});const blob=await response.blob();const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='defensowrix-early-access.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='CSV export downloaded.';}catch(error){status.textContent=/permission|admin|denied|unauthorized/i.test(error.message)?'Access denied. Your account cannot export these requests.':'Could not export Early Access data. Please refresh and try again.';}finally{button.disabled=false;}};
 document.getElementById('ea-export').addEventListener('click',exportCsv);
 document.getElementById('ea-refresh').addEventListener('click',()=>load());document.getElementById('ea-prev').addEventListener('click',()=>{if(page>1){page--;load();}});document.getElementById('ea-next').addEventListener('click',()=>{if(page<totalPages){page++;load();}});document.getElementById('ea-status').addEventListener('change',()=>{page=1;load();});document.getElementById('ea-search').addEventListener('input',()=>{clearTimeout(delay);delay=setTimeout(()=>{page=1;load();},300);});load();
}
